"""Loads app/seed_data.json (generated by scripts/import_excel.py from the Excel blacklist).

Pre-launch only: delete this module and the JSON once the app points at Azure SQL.
"""
import json
from pathlib import Path

from .models import Channel, IdentifierType, ReasonCode
from .repository import InMemoryRepository

SEED_FILE = Path(__file__).with_name("seed_data.json")


def load_repository(path: Path = SEED_FILE) -> InMemoryRepository:
    data = json.loads(path.read_text(encoding="utf-8"))
    return InMemoryRepository(
        [Channel(**c) for c in data["channels"]],
        [ReasonCode(**r) for r in data["reason_codes"]],
        [IdentifierType(**t) for t in data["identifier_types"]],
        data["listings"],
    )
